/* @lc app=leetcode id=2850 lang=kotlin */
class Solution { fun minimumMoves(grid: Array<IntArray>): Int = (0..2).flatMap { r -> (0..2).map { c -> r to c } }.let { coords -> coords.filter { grid[it.first][it.second] == 0 } to coords.flatMap { (r, c) -> List(kotlin.math.max(0, grid[r][c] - 1)) { r to c } } }.let { (to, from) -> kotlin.DeepRecursiveFunction<Pair<Int, Int>, Int> { (idx, mask) -> if (idx == from.size) 0 else (0 until to.size).filter { i -> (mask and (1 shl i)) == 0 }.minOf { i -> kotlin.math.abs(from[idx].first - to[i].first) + kotlin.math.abs(from[idx].second - to[i].second) + callRecursive(idx + 1 to (mask or (1 shl i))) } }.call(0 to 0) } }